import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {
  const [selectedIncome, setSelectedIncome] = useState("");
  const navigate = useNavigate();

  const handleSelect = (type) => {
    setSelectedIncome(type);
  };

  const handleContinue = () => {
    if (!selectedIncome) {
      alert("Please select an income type");
      return;
    }

    if (onNext) onNext(selectedIncome);
    navigate("/questionnaire");
  };

  return (
    <div className="income-category-container">
      <h2 className="title">Select Your Income Category</h2>

      <div className="income-options">
        <button
          className={`income-btn ${selectedIncome === "Salary" ? "active" : ""}`}
          onClick={() => handleSelect("Salary")}
        >
          Salary
        </button>

        <button
          className={`income-btn ${selectedIncome === "Business" ? "active" : ""}`}
          onClick={() => handleSelect("Business")}
        >
          Business
        </button>

        <button
          className={`income-btn ${selectedIncome === "Student" ? "active" : ""}`}
          onClick={() => handleSelect("Student")}
        >
          Student
        </button>

        <button
          className={`income-btn ${selectedIncome === "No Income" ? "active" : ""}`}
          onClick={() => handleSelect("No Income")}
        >
          No Income
        </button>
      </div>

      <button className="continue-button" onClick={handleContinue}>
        Continue
      </button>
    </div>
  );
}

export default IncomeCategory;
